-- sum amount_due for overdue invoices
SELECT SUM(amount_due) FROM C:\Users\sandeeppawar\.copilot\session-state\4fc1d5d0-25b1-4323-b111-f91ae7bc94cd\files\dbo_eval\csv\invoices.csv WHERE status = 'overdue';
-- sum amount_paid for overdue invoices joining with payments
SELECT SUM(p.amount_paid) 
FROM C:\Users\sandeeppawar\.copilot\session-state\4fc1d5d0-25b1-4323-b111-f91ae7bc94cd\files\dbo_eval\csv\invoices.csv i JOIN C:\Users\sandeeppawar\.copilot\session-state\4fc1d5d0-25b1-4323-b111-f91ae7bc94cd\files\dbo_eval\csv\payments.csv p ON i.invoice_id = p.invoice_id
WHERE i.status = 'overdue';

SELECT ROUND(SUM(amount_due)::numeric, 2) AS total_amount_due
FROM invoices
WHERE DATE_TRUNC('month', invoice_date) = (
  SELECT MAX(DATE_TRUNC('month', invoice_date)) FROM invoices
);

SELECT AVG(num_payments) AS mean_payments_per_invoice
FROM (
    SELECT invoice_id, COUNT(payment_id) AS num_payments
    FROM payments
    GROUP BY invoice_id
) t;
